<template>
        <button :style="style" :disabled="isDisabled" @click="onClickButton" class="lm-button {{isActive ? 'active' : ''}} {{type}}-button {{theme}} {{size}} {{ isAnimate ? 'animate' : ''}} {{type=='split' ? 'split-left' : ''}}">
            <svg class="icons{{realIcon.size}} icon-{{realIcon.theme}}" v-if="realIcon && realIcon.id && iconPosition=='left'"><use xlink:href="#{{realIcon.id}}"></use></svg>
            <slot v-if="!isIconPassed || !isTextPassed"></slot>
            <template v-if="isTextPassed">
                {{realText}}
            </template>
            <svg class="icons{{realIcon.size}} icon-{{realIcon.theme}}" v-if="realIcon && realIcon.id && iconPosition=='right'"><use xlink:href="#{{realIcon.id}}"></use></svg>
        </button>
        <button v-if="type == 'split'" class="lm-button split-right {{splitBtnTheme}} {{ isAnimate ? 'animate' : ''}}">
            <svg class="icons{{splitIcon.size}} icon-{{splitIcon.theme}}" v-if="splitIcon && splitIcon.id"><use xlink:href="#{{splitIcon.id}}"></use></svg>
            {{splitBtnText}}
        </button>
</template>

<script>
    import '../common/scss/common.scss';
    import './button.scss';

    var iconPropConfig =  {
        type: [Object, String],
        coerce: function (icon) {
            if (icon) {
                if (typeof icon == 'string') {
                    icon = {
                        id: icon
                    };
                }

                icon.size = icon.size || 18;
            }

            return icon;
        }
    };

    var propThemeConfig = {
        type: [String],
        default: 'gray',
        validator: function (value) {
            return ['blue', 'gray', 'white'].indexOf(value) > -1;
        }
    };

    export default {
        props: {
            /**
             * define the button type the type can be plain, icon, split, menu and toggle buttons
             */
            type: {
                type: [String],
                default: 'plain',
                validator: function (value) {
                    return ['plain', 'icon', 'split', 'menu', 'toggle'].indexOf(value) > -1;
                }
            },
            /**
             * define button size, the type can be empty, small, small-small
             */
            size: {
                type: [String],
                default: ''
            },
            /**
             * define the theme of the button, the theme can be gray, blue and white
             */
            theme: propThemeConfig,
            isAnimate: {
                type: [Boolean],
                default: true
            },
            isDisabled: {
                type: [Boolean],
                default: false
            },
            /**
             * Specify the icon of the button
             * example:
             * icon="icon-settings"
             * icon="{size: 26, theme: 'gray', id: 'icon-lookup-26'}"
             */
            icon: iconPropConfig,
            /**
             * iconPosition means the position of the icon relative to the button text
             * example:
             * icon-position="left"
             * icon-position="right"
             */
            iconPosition: {
                type: [String]
            },
            /**
             * Define the button text
             */
            text: {
                type: [String]
            },
            /**
             * Specify the split icon for the split buttons, the config style is the same with the icon
             */
            splitIcon: iconPropConfig,
            /**
             * Specify the button text of the split button
             */
            splitBtnText: {
                type: [String]
            },
            /**
             * Specify the theme of the split button
             */
            splitBtnTheme: {
                type: [String],
                validator: function (value) {
                    return ['blue', 'gray', 'white'].indexOf(value) > -1;
                }
            },
            /**
             * Specify the icon of the toggle button in active status
             */
            activeIcon: iconPropConfig,
            /**
             * Specify the text of the toggle button in active status
             */
            activeText: {
                type: [String]
            },
            isActive: {
                type: [Boolean],
                default: false
            },
            style: {
                type: [String],
                default: ''
            }
        },
        data() {
            return {

            };
        },
        created() {
            var defaultIconPosition = this.type == 'menu' ? 'right' : 'left';

            this.iconPosition = this.iconPosition || defaultIconPosition;

            if (this.icon) {
                if (!this.icon.theme && this.theme == 'blue') {
                    this.icon.theme = 'white';
                }

                this.icon.theme = this.transformIconColor(this.icon.theme);
            }

            if (this.type == 'split' && this.splitIcon) {
                if (!this.splitIcon.theme && this.icon && this.icon.theme) {
                    this.splitIcon.theme = this.icon.theme;
                }

                this.splitIcon.theme = this.transformIconColor(this.splitIcon.theme);
            }

            if (!this.splitBtnTheme) {
                this.splitBtnTheme = this.theme;
            }

            if (this.type == 'toggle' && this.activeIcon) {
                this.activeIcon.theme = this.transformIconColor(this.activeIcon.theme, 'white');
            }
        },
        computed: {
            isIconPassed() {
                return !!(this.realIcon && this.realIcon.id);
            },
            isTextPassed() {
                return this.realText != undefined;
            },
            realIcon() {
                if (this.type == 'toggle' && this.isActive) {
                    return this.activeIcon;
                } else {
                    return this.icon;
                }
            },
            realText() {
                if (this.type == 'toggle' && this.isActive) {
                    return this.activeText;
                } else {
                    return this.text;
                }
            }
        },
        methods: {
            transformIconColor(color, defaultColor = 'gray') {
                let colorMap = {
                    blue: 'primary1',
                    lightGray: 'light-gray'
                };

                return colorMap[color] || color || defaultColor;

            },
            onClickButton() {
                var me = this;
                this.isActive = !this.isActive;

                Vue.nextTick(function () {
                    me.$emit('toggle', me.isActive);
                });
            }
        }
    };
</script>



